<?php
$lines = [];
while (!feof(STDIN)) {
    $line = trim(fgets(STDIN));
    if ($line !== '') {
        $lines[] = $line;
    }
}

$n = (int)$lines[0][0];
$m = (int)$lines[0][2];

$aDigits = array_map('intval', explode(' ', $lines[1]));
$bDigits = array_map('intval', explode(' ', $lines[2]));

$aSet = array_flip($aDigits);
$bSet = array_flip($bDigits);

$min = PHP_INT_MAX;

// Check single-digit numbers
for ($d = 1; $d <= 9; $d++) {
    if (isset($aSet[$d]) && isset($bSet[$d])) {
        $min = min($min, $d);
    }
}

// Check two-digit numbers
for ($d1 = 1; $d1 <= 9; $d1++) {
    for ($d2 = 0; $d2 <= 9; $d2++) {
        $num = $d1 * 10 + $d2;
        $hasA = isset($aSet[$d1]) || isset($aSet[$d2]);
        $hasB = isset($bSet[$d1]) || isset($bSet[$d2]);
        if ($hasA && $hasB) {
            $min = min($min, $num);
        }
    }
}

echo $min . "\n";
?>
